css:
/* Change this material and make it yours. */
body {
  margin: 0;
  padding: 24px;
  min-height: 100vh;
  box-sizing: border-box;
  display: grid;
  place-items: center;
  background: #102a31;
  color: #e9f3ed;
  font-family: ui-monospace, monospace;
}
button,
input {
  font: inherit;
}
.lm-lab {
  width: 100%;
  max-width: 380px;
}
.lm-lab .showcase {
  --sg-ink: #e9f3ed;
  --sg-muted: #adc2c5;
  --sg-ember: #ffaa71;
  --sg-teal: #70d5c5;
  --lumen-bg: #16323680;
  --lumen-solid-bg: #163236;
  --lumen-glow-color: var(--sg-teal);
  --lumen-border-glow-color: #b4eee1;
  --lumen-glow-opacity: 0.2;
  --lumen-border-opacity: 0.75;
  --lumen-glow-size: 260px;
  --lumen-radius: 14px;
  --lumen-blur: 0px;
  --lumen-border-width: 1px;
  --lumen-border-color: #92b4ad30;
  color: var(--sg-ink);
  padding: 30px 0 32px;
  border-top: 0;
  scroll-margin-top: 100px;
}
.lm-lab .showcase * {
  box-sizing: border-box;
}
.lm-lab .showcase [hidden] {
  display: none !important;
}
.lm-lab #showcase-count {
  margin: 0;
  color: var(--sg-muted);
  font-size: 10px;
  white-space: nowrap;
}
.lm-lab .example {
  min-width: 0;
  border: 2px solid #8cafab30;
  border-radius: var(--studio-radius, 4px);
  background: #0b2028;
  overflow: hidden;
}
.lm-lab .showcase[data-enhanced]:not([data-in-view]),
.lm-lab .showcase[data-enhanced] .example:not([data-visible]) {
  --lumen-x: -100vw;
  --lumen-y: -100vh;
}
.lm-lab .showcase-demo {
  position: relative;
  padding: 24px;
  min-height: 220px;
  overflow: clip;
  isolation: isolate;
  font-size: 12px;
  line-height: 1.5;
}
.lm-lab .showcase-demo h3 {
  font-size: 25px;
  line-height: 1.15;
  letter-spacing: -0.055em;
  margin: 14px 0;
}
.lm-lab .showcase-demo p {
  margin: 0;
}
.lm-lab .showcase-demo button {
  min-height: 44px;
  font: inherit;
  font-size: 11px;
  color: var(--sg-ink);
  padding: 9px 12px;
  cursor: pointer;
}
.lm-lab .showcase-demo button[aria-pressed="true"] {
  color: var(--sg-ember);
}
.lm-lab .showcase :is(button, input, a, pre):focus-visible {
  outline: 2px solid var(--sg-ember);
  outline-offset: 3px;
}
.lm-lab .demo-kicker {
  display: block;
  color: var(--sg-muted);
  font-size: 8px;
  line-height: 1.5;
  letter-spacing: 0.13em;
}
.lm-lab .showcase-demo :is(button, input, label) {
  position: relative;
}
.lm-lab .demo-player {
  padding: 18px;
  background: #283c40;
}
.lm-lab .record-art {
  height: 190px;
  position: relative;
  overflow: hidden;
  border-radius: 10px 10px 0 0;
  background: linear-gradient(125deg, #bcbaa0, #d48e69);
}
.lm-lab .record-art > span {
  position: absolute;
  z-index: 1;
  top: 18px;
  left: 16px;
  font-size: 15px;
  line-height: 1;
  letter-spacing: -0.05em;
  font-weight: 800;
  color: #253a34;
}
.lm-lab .record-disc {
  position: absolute;
  width: 220px;
  aspect-ratio: 1;
  border-radius: 50%;
  top: 35px;
  right: -40px;
  background:
    radial-gradient(circle, #ffaa71 0 5%, #142725 5% 15%, transparent 15%),
    repeating-radial-gradient(circle, #213e3c 0 2px, #142725 3px 4px);
  box-shadow: -14px 12px 28px #18383270;
}
.lm-lab .player-panel {
  padding: 20px 16px 15px;
  margin-top: -26px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 14px;
  --lumen-blur: 12px;
  --lumen-bg: #153035b3;
}
.lm-lab .player-panel h3 {
  font-size: 18px;
  margin: 9px 0 5px;
}
.lm-lab .player-panel p {
  color: var(--sg-muted);
  font-size: 10px;
}
.lm-lab .player-panel .round-button {
  align-self: center;
  --lumen-radius: 50%;
  width: 44px;
}
.lm-lab .waveform {
  display: flex;
  gap: 5px;
  height: 35px;
  align-items: center;
  grid-column: 1 / -1;
}
.lm-lab .waveform i {
  display: block;
  flex: 1;
  height: 35%;
  border-radius: 2px;
  background: var(--sg-teal);
  transform-origin: center;
  animation: lm-wave 850ms ease-in-out infinite alternate;
  animation-play-state: paused;
}
.lm-lab .waveform i:nth-child(3n) {
  height: 95%;
  animation-delay: -200ms;
}
.lm-lab .waveform i:nth-child(3n + 1) {
  height: 65%;
  animation-delay: -500ms;
}
.lm-lab .example[data-visible] .demo-player[data-playing] .waveform i,
.lm-lab .showcase:not([data-enhanced]) .demo-player[data-playing] .waveform i {
  animation-play-state: running;
}
@keyframes lm-wave {
  to {
    transform: scaleY(0.25);
  }
}
@keyframes lm-edge {
  to {
    background-position: 100% 100%;
  }
}
@media (max-width: 600px) {
  .lm-lab .showcase {
    padding-top: 34px;
  }
  .lm-lab #showcase-count {
    margin-top: 14px;
  }
  .lm-lab .showcase-demo {
    padding-inline: 24px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .lm-lab .showcase *,
  .lm-lab .showcase *::before,
  .lm-lab .showcase *::after {
    animation: none !important;
    transition: none !important;
  }
  .lm-lab .glass-dock button:is(:hover, :focus-visible) {
    transform: none;
  }
}
@media (prefers-reduced-transparency: reduce) {
  .lm-lab .showcase .lumenmorph {
    --lumen-blur: 0px;
    background: #173538;
  }
  .lm-lab .showcase .foil-pass {
    background: #b0ba9b;
  }
}
@media (forced-colors: active) {
  .lm-lab .showcase,
  .lm-lab .showcase * {
    color: CanvasText !important;
    text-shadow: none !important;
    box-shadow: none !important;
  }
  .lm-lab
    .showcase
    :is(
      .example,
      .showcase-demo,
      .example-caption,
      .showcase-dialog,
      .lumenmorph,
      input,
      button
    ) {
    background: Canvas !important;
    border-color: CanvasText;
  }
  .lm-lab
    .showcase
    :is(.beam-ring, .ignite-halo, .weather-sky, .marble-line, .mesh-lines) {
    display: none;
  }
  .lm-lab .showcase :is(.specimen-word, .outline-word) {
    background: none;
    -webkit-text-stroke: 0;
  }
  .lm-lab .showcase :is([aria-pressed="true"], [aria-current="step"]) {
    outline: 2px solid Highlight;
  }
}
@media (prefers-reduced-motion: reduce) {
  .lm-lab .showcase .light-chart i,
  .lm-lab .showcase .palette-orb {
    transition: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .lm-lab .focus-tasks label,
  .lm-lab .spark-rating span,
  .lm-lab .demo-rating::before {
    transition: none;
  }
}
.lm-lab .showcase {
  padding: 0;
  border: 0;
}
.lm-lab .example {
  border-radius: 4px;
}

